    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><meta name="description" content="BeliefWeave — Governing When Memory May Change Behavior, by Aura Yavary.">{extra_head}<style>{style}</style></head><body><main class="wrap">{body}</main></body></html>'''

